import functools
import inspect

def get_call_globals(call):
    unwrapped = inspect.unwrap(call)
    while hasattr(unwrapped, "func"):
        unwrapped = inspect.unwrap(unwrapped.func)
    if hasattr(unwrapped, "__globals__"):
        return unwrapped.__globals__
    module = inspect.getmodule(unwrapped)
    if module:
        return module.__dict__
    return {}

